const result={schema:'agentnet-interaction-reconciliation/v2',review:{complete:false},reports:reports.length,input_dispatch:[...new Set(reports.map(r=>r.inputDispatch))],comic_react:{total:summary('TOTAL',rows),scope:summary('SCOPE',scopedRows),by_feature_file:files,trusted_interactions:trusted,named_expectations:{rows:named,bound:named.filter(x=>x.control_id).length,unbound:named.filter(x=>!x.control_id).length,qualified_rows:named.filter(x=>x.qualified).length,primitive_rows:named.filter(x=>String(x.assertion_kind).startsWith('primitive-')).length,primitive_qualified:named.filter(x=>String(x.assertion_kind).startsWith('primitive-')&&x.qualified).length,unknown_binding:named.filter(x=>x.control_id&&!rows.some(r=>r.definition_id===x.control_id)).map(x=>x.control_id),cells:reports.filter(r=>r.engine).map(r=>({cell:[r.writeDelayMs?'held':'normal',r.suite,r.viewport?r.viewport.width+'x'+r.viewport.height:'?',r.engine].join('/'),execution:r.execution||null,ok:r.ok??null,named_rows:(r.actions||[]).filter(a=>a.trusted).length,definitions:(c=>disposition(rows.map(x=>x.definition_id),id=>named.filter(x=>x.cell===c&&x.control_id===id)))([r.writeDelayMs?'held':'normal',r.suite,r.viewport?r.viewport.width+'x'+r.viewport.height:'?',r.engine].join('/'))})),rule:'a definition is within_bound only when every observed named row for it qualifies (handler kind, or a source-attributed primitive-open/primitive-close own-state transition); failed and unexecuted cells are listed; applicability of unobserved cells is not certified'},unreachable},unattributed_untagged_rendered:gaps.filter(g=>!g.nearest_control),populations_without_rendered_binding:['overlay','standalone','static','native-desktop','native-android'],applicability_rule,notes:'Only trusted Playwright input plus an asserted visible local change qualifies execution. Mocked fixture cannot prove native DB/sync contention.'};
